import { useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Plus } from 'lucide-react'
import { ObjectiveCard } from '@/shared/ui/ObjectiveCard'
import { objectivesService } from '@/integrations/supabase/objectives'

export function ProjectOrganiserPage() {
  const { projectId } = useParams()
  const navigate = useNavigate()
  const qc = useQueryClient()
  const [showNew, setShowNew] = useState(false)
  const [title, setTitle] = useState('')

  const { data: objectives = [], isLoading } = useQuery({
    queryKey: ['objectives', projectId],
    queryFn: () => objectivesService.listObjectives(projectId ?? ''),
    enabled: !!projectId,
  })

  const createMut = useMutation({
    mutationFn: () => objectivesService.createObjective({
      projectId: projectId ?? '',
      title,
      status: 'draft',
      tags: [],
      participants: [],
      valueMode: 'none',
      tasksCount: 0,
      completedTasksCount: 0,
    }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['objectives', projectId] })
      setShowNew(false)
      setTitle('')
      toast.success('Objective created')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="font-semibold">Objectives</h2>
            <p className="text-sm text-muted-foreground">{objectives.length} objectives</p>
          </div>
          <button onClick={() => setShowNew(true)} className="flex items-center gap-1.5 text-sm bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90">
            <Plus size={14} /> New objective
          </button>
        </div>

        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : objectives.length === 0 && !showNew ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-muted-foreground">No objectives yet</p>
            <button onClick={() => setShowNew(true)} className="mt-3 inline-flex items-center gap-1.5 text-sm text-accent hover:underline">
              <Plus size={14} /> Add first objective
            </button>
          </div>
        ) : (
          <div className="flex flex-col gap-3">
            {objectives.map((obj) => (
              <ObjectiveCard key={obj.id} objective={obj} onClick={() => navigate(`/app/objective/${obj.id}`)} />
            ))}
          </div>
        )}

        {showNew && (
          <div className="mt-4 rounded-xl border border-accent/30 bg-accent/5 p-4">
            <p className="text-sm font-medium mb-2">New objective</p>
            <input value={title} onChange={(e) => setTitle(e.target.value)} autoFocus placeholder="Objective title..."
              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent mb-2"
              onKeyDown={(e) => {
                if (e.key === 'Escape') { setShowNew(false); setTitle('') }
                if (e.key === 'Enter' && title) createMut.mutate()
              }}
            />
            <div className="flex gap-2">
              <button onClick={() => createMut.mutate()} disabled={!title || createMut.isPending} className="text-xs bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90 disabled:opacity-50">
                {createMut.isPending ? 'Creating…' : 'Create'}
              </button>
              <button onClick={() => { setShowNew(false); setTitle('') }} className="text-xs text-muted-foreground hover:text-foreground px-3 py-1.5">Cancel</button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
